import subprocess
import sys
import shutil
from pathlib import Path
GRADE_SCRIPT_PATH = Path('/opt/lms/scripts/recalculate_grades.py')
GRADE_DRAFT_CACHE_ROOT = Path('/var/cache/lms/grade_drafts')

def run_course_grade_recalculation_job(course_id: str, grading_scheme: str='weighted') -> dict:
    if not GRADE_SCRIPT_PATH.exists():
        return {'success': False, 'error': 'Recalculation script not found'}
    command_line_arguments_for_job = [sys.executable, str(GRADE_SCRIPT_PATH), '--course-id', course_id, '--scheme', grading_scheme]
    completed_process_result = subprocess.run(command_line_arguments_for_job, capture_output=True, text=True, timeout=600)
    job_was_successful = completed_process_result.returncode == 0
    standard_output_tail_lines = completed_process_result.stdout.strip().splitlines()[-10:]
    standard_error_text_output = completed_process_result.stderr.strip()
    if job_was_successful:
        # Remove stale cached draft grade snapshots for this course
        stale_draft_directory = GRADE_DRAFT_CACHE_ROOT / Path(course_id).name
        if stale_draft_directory.is_dir():
            shutil.rmtree(stale_draft_directory, ignore_errors=True)
    return {'success': job_was_successful, 'return_code': completed_process_result.returncode, 'output_tail': standard_output_tail_lines, 'error': standard_error_text_output if not job_was_successful else None}
